	internal class _Anon_KeyAdapter_1 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent e) {
				KeyStroke keyStrokeForEvent = KeyStroke.getKeyStrokeForEvent(e);
				if (SUBMIT_KEYSTROKE.equals(keyStrokeForEvent)) {
					okCallback();
